-- migrate:up
create or replace function pulse.fair_publish(pe uuid,action text) returns uuid language plpgsql security definer set search_path=pulse,pg_temp as $$
declare d jsonb;sc uuid;nid uuid;pr pulse_priv.fair_projection%rowtype;dt timestamptz;days int:=0;wd int[];attempts int:=0;begin
 perform fair_review(pe);perform pg_advisory_xact_lock(hashtextextended('fair:'||current_org()::text,0));
 if action='prepare' then
 d:=fair_delivery(pe);if d->>'start' is null then raise exception 'Establish coverage before preparing a measure' using errcode='22023';end if;
 update pulse_priv.fair_projection set state='superseded' where org_id=current_org() and person_id=pe and dimension='delivery';
 insert into score(org_id,subject_type,subject_id,metric,period_start,period_end,value,n_effective,sufficiency,explanation,model_name,model_version,visibility)
 values(current_org(),'person',pe,'fair_delivery',(d->>'start')::date,(d->>'end')::date,case when (d->>'denominator')::numeric>0 then (d->>'numerator')::numeric/(d->>'denominator')::numeric end,(d->>'sample')::int,case when coalesce((d->>'gate')::boolean,false) then 'enough' else 'thin' end,d,'fair-work','v1','person') returning id into sc;
 select work_days into wd from hr_policy where org_id=current_org();wd:=coalesce(wd,array[1,2,3,4,5]);dt:=now();while days<2 and attempts<370 loop dt:=dt+interval '1 day';attempts:=attempts+1;if extract(isodow from dt at time zone 'Asia/Kolkata')::int=any(wd) and not exists(select 1 from holiday where org_id=current_org() and day=(dt at time zone 'Asia/Kolkata')::date and not optional) and not exists(select 1 from leave_request where org_id=current_org() and person_id=pe and status='approved' and (dt at time zone 'Asia/Kolkata')::date between from_date and to_date) then days:=days+1;end if;end loop;if days<2 then raise exception 'No eligible employee review window calendar required' using errcode='22023';end if;
 insert into pulse_priv.fair_projection(org_id,person_id,score_id,dimension,state,review_after,reviewer,body) values(current_org(),pe,sc,'delivery','self_visible',dt,current_viewer(),d) returning id into nid;return nid;
 elsif action='publish' then
 select * into pr from pulse_priv.fair_projection where org_id=current_org() and person_id=pe and dimension='delivery' and state='self_visible' order by at desc limit 1 for update;
 d:=fair_delivery(pe);
 if pr.id is null or now()<pr.review_after or not coalesce((d->>'gate')::boolean,false) or d<>pr.body or exists(select 1 from pulse_priv.fair_dispute where org_id=current_org() and person_id=pe and dimension='delivery' and state='open') then raise exception 'Self review window evidence and dispute gate must pass' using errcode='42501';end if;
 update pulse_priv.fair_projection set state='manager_visible' where id=pr.id;return pr.id;
 else raise exception 'Choose prepare or publish' using errcode='22023';end if;
end $$;
create or replace function pulse.fair_review_options() returns jsonb language plpgsql security definer set search_path=pulse,pg_temp as $$
begin perform fair_self();return jsonb_build_object(
 'people',coalesce((select jsonb_agg(jsonb_build_object('id',id,'name',display_name)) from person where org_id=current_org() and side='staff' and status='active'),'[]'),
 'baselines',coalesce((select jsonb_agg(jsonb_build_object('id',b.id,'taskId',b.task_id,'personId',b.person_id,'family',b.family,'unitKind',b.unit_kind,'weight',b.weight,'share',b.share,'due',b.due,'eligible',b.eligible)) from pulse_priv.fair_baseline b where org_id=current_org() and (authority=current_viewer() or viewer_is('admin','leadership') or manages(b.person_id)) and not exists(select 1 from pulse_priv.fair_baseline x where x.supersedes=b.id)),'[]'),
 'credits',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'personId',c.person_id,'acceptanceId',c.acceptance_id,'family',c.family,'weight',c.weight,'share',c.share)) from pulse_priv.fair_credit c where org_id=current_org() and authority=current_viewer() and not exists(select 1 from pulse_priv.fair_credit x where x.supersedes=c.id)),'[]'),
 'experiments',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'personId',x.person_id,'skill',x.skill,'anchor',x.anchor,'hypothesis',x.hypothesis,'state',x.state)) from pulse_priv.fair_experiment x join pulse_priv.fair_note n on n.id=x.note_id where x.org_id=current_org() and n.author=current_viewer()),'[]'),
 'tasks',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'title',t.body->>'title','assigneeId',assignee_id,'reviewerId',reviewer_id,'state',state,'due',t.body->>'due')) from pulse_priv.delivery_task t where org_id=current_org() and (reviewer_id=current_viewer() or owner_id=current_viewer() or viewer_is('admin','leadership'))),'[]'),
 'acceptances',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'taskId',e.task_id,'version',e.body->>'version','at',e.at,'family',(select a.project_id::text||':'||coalesce(a.family,a.id::text) from version v join asset a on a.id=v.asset_id where v.id::text=e.body->>'version'))) from pulse_priv.delivery_event e where org_id=current_org() and kind='accepted' and actor=current_viewer()),'[]'),
 'corrections',coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'personId',d.person_id,'dimension',dimension,'reason',reason,'state',state)) from pulse_priv.fair_dispute d where org_id=current_org() and state='open' and (viewer_is('admin','leadership') or manages(d.person_id))),'[]'));
end $$;
-- Versioned, purpose-specific notices precede any future optional sensing. No sensor is activated here.
create table pulse_priv.fair_notice(
 org_id uuid not null references pulse.org(id),id uuid primary key default gen_random_uuid(),version text not null,purpose text not null check(purpose='optional_work_context'),
 body jsonb not null,authority uuid not null references pulse.person(id),approved_at timestamptz not null default now(),withdrawn_at timestamptz,unique(org_id,version,purpose));
create table pulse_priv.fair_consent(
 org_id uuid not null references pulse.org(id),id uuid primary key default gen_random_uuid(),person_id uuid not null references pulse.person(id),notice_id uuid not null references pulse_priv.fair_notice(id),
 device_id uuid not null references pulse.device(id),kind text not null check(kind in('grant','withdraw')),at timestamptz not null default now());
create table pulse_priv.fair_break(
 org_id uuid not null references pulse.org(id),person_id uuid primary key references pulse.person(id),paused boolean not null default true,at timestamptz not null default now());
do $$declare t text;begin foreach t in array array['fair_notice','fair_consent','fair_break'] loop
 execute format('alter table pulse_priv.%I enable row level security',t);execute format('alter table pulse_priv.%I force row level security',t);
 execute format('create policy tenant on pulse_priv.%I using(org_id=pulse.current_org()) with check(org_id=pulse.current_org())',t);
 execute format('create trigger audit_mutation after insert or update or delete on pulse_priv.%I for each row execute function pulse.audit_mutation()',t);
 end loop;end $$;
create function pulse.fair_notice_approve(p jsonb) returns uuid language plpgsql security definer set search_path=pulse,pg_temp as $$
declare nid uuid;begin perform fair_self();if not viewer_is('admin') then raise exception 'EA policy authority required' using errcode='42501';end if;
 if p->>'purpose' is distinct from 'optional_work_context' or length(trim(coalesce(p->>'version','')))<3 or jsonb_typeof(p->'dataItems') is distinct from 'array' or jsonb_array_length(p->'dataItems')=0 or exists(select 1 from jsonb_array_elements_text(p->'dataItems') i where i not in('work_app_category','focus_idle_aggregate','render_export_metadata','structural_edit_delta','authorized_project_id','explicit_shoot_wrap')) or jsonb_typeof(p->'apps') is distinct from 'array' or jsonb_typeof(p->'domains') is distinct from 'array' or jsonb_typeof(p->'workWindow') is distinct from 'object' or length(trim(coalesce(p->>'audience','')))<3 or length(trim(coalesce(p->>'rightsContact','')))<3 or length(trim(coalesce(p->>'withdrawalFlow','')))<3 or (p->>'rawDays')::int not between 1 and 60 or (p->>'derivedDays')::int not between 1 and 180 or p->>'rawDays' is null or p->>'derivedDays' is null or p->>'deletionTest' is distinct from 'passed' then raise exception 'Purpose notice allowlists retention rights withdrawal and deletion evidence required' using errcode='22023';end if;
 insert into pulse_priv.fair_notice(org_id,version,purpose,body,authority) values(current_org(),p->>'version',p->>'purpose',p,current_viewer()) returning id into nid;return nid;end $$;
create function pulse.fair_consent_set(notice uuid,device uuid,kind text) returns uuid language plpgsql security definer set search_path=pulse,pg_temp as $$
declare pe uuid:=fair_self();nid uuid;begin
 if kind='withdraw' then
 if not exists(select 1 from pulse_priv.fair_consent where org_id=current_org() and person_id=pe and notice_id=notice and device_id=device and fair_consent.kind='grant') then raise exception 'Your existing collection permission receipt required' using errcode='42501';end if;
 elsif kind<>'grant' or not exists(select 1 from pulse_priv.fair_notice where org_id=current_org() and id=notice and withdrawn_at is null) or not exists(select 1 from pulse.device d where d.org_id=current_org() and d.id=device and d.revoked_at is null and (d.default_person_id=pe or exists(select 1 from device_assignment where org_id=current_org() and device_id=d.id and person_id=pe and valid_from<=now() and (valid_to is null or valid_to>now())))) or exists(select 1 from person where id=pe and tracking_excluded) then raise exception 'Approved notice and currently assigned eligible device required' using errcode='42501';end if;
 insert into pulse_priv.fair_consent(org_id,person_id,notice_id,device_id,kind) values(current_org(),pe,notice,device,kind) returning id into nid;return nid;end $$;
create function pulse.fair_break_set(paused boolean) returns void language plpgsql security definer set search_path=pulse,pg_temp as $$
begin perform fair_self();insert into pulse_priv.fair_break(org_id,person_id,paused) values(current_org(),current_viewer(),paused) on conflict(person_id) do update set paused=excluded.paused,at=now();end $$;
create function pulse.fair_collection() returns jsonb language plpgsql security definer set search_path=pulse,pg_temp as $$
begin perform fair_self();return jsonb_build_object('sensingEnabled',false,'osPermissionSeparate',true,'paused',coalesce((select paused from pulse_priv.fair_break where org_id=current_org() and person_id=current_viewer()),true),
 'notices',coalesce((select jsonb_agg(jsonb_build_object('id',id,'version',version,'purpose',purpose,'body',body)) from pulse_priv.fair_notice where org_id=current_org() and withdrawn_at is null),'[]'),
 'receipts',coalesce((select jsonb_agg(jsonb_build_object('id',id,'notice',notice_id,'device',device_id,'kind',kind,'at',at)) from pulse_priv.fair_consent where org_id=current_org() and person_id=current_viewer()),'[]'),
 'devices',coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'label',label,'platform',platform)) from pulse.device d where org_id=current_org() and revoked_at is null and (default_person_id=current_viewer() or exists(select 1 from device_assignment where org_id=current_org() and device_id=d.id and person_id=current_viewer() and valid_from<=now() and (valid_to is null or valid_to>now())))),'[]'));end $$;
revoke all on function pulse.fair_notice_approve(jsonb),pulse.fair_consent_set(uuid,uuid,text),pulse.fair_break_set(boolean),pulse.fair_collection() from public;
grant execute on function pulse.fair_notice_approve(jsonb),pulse.fair_consent_set(uuid,uuid,text),pulse.fair_break_set(boolean),pulse.fair_collection() to pulse_api;
create or replace function pulse.fair_state(pe uuid default null) returns jsonb language plpgsql security definer set search_path=pulse,pg_temp as $$
declare own boolean;target uuid:=coalesce(pe,fair_self());begin perform fair_self();own:=target=current_viewer();
 if not own and not((manages(target) or viewer_is('admin','leadership')) and exists(select 1 from pulse_priv.fair_access where org_id=current_org() and person_id=target and manager_id=current_viewer() and purpose='supportive_coaching' and revoked_at is null)) then raise exception 'Current purpose and employee access required' using errcode='42501';end if;
 return jsonb_build_object('self',own,'viewer',current_viewer(),'person',(select display_name from person where id=target and org_id=current_org()),
 'delivery',case when own then fair_delivery(target) end,
 'projections',coalesce((select jsonb_agg(jsonb_build_object('id',id,'dimension',dimension,'state',state,'reviewAfter',review_after,'body',body)) from pulse_priv.fair_projection p where org_id=current_org() and person_id=target and state<>'superseded' and (own or state='manager_visible' and not exists(select 1 from pulse_priv.fair_dispute where org_id=current_org() and person_id=target and dimension=p.dimension and state='open'))),'[]'),
 'receipts',case when own then coalesce((select jsonb_agg(jsonb_build_object('id',b.id,'taskId',b.task_id,'title',t.body->>'title','project',(select coalesce(title,name) from project where id=t.project_id),'family',b.family,'weight',b.weight,'share',b.share,'due',b.due,'personId',b.person_id,'original',b.weight*b.share,'eligible',b.eligible,'reason',case when b.supersedes is not null then b.reason end,'version',c.version,'acceptedAt',e.at,'source','Native exact-version acceptance','basis',coalesce(c.reason,'Reviewed planned commitment'),'reviewer',(select display_name from person where id=c.authority),'blocked',exists(select 1 from pulse_priv.delivery_blocker where org_id=current_org() and task_id=t.id and ended_at is null))) from pulse_priv.fair_baseline b join pulse_priv.delivery_task t on t.id=b.task_id
 left join pulse_priv.fair_credit c on c.org_id=b.org_id and c.task_id=b.task_id and c.person_id=b.person_id and c.family=b.family and not exists(select 1 from pulse_priv.fair_credit x where x.supersedes=c.id) left join pulse_priv.delivery_event e on e.id=c.acceptance_id
 where b.org_id=current_org() and b.person_id=target and not exists(select 1 from pulse_priv.fair_baseline x where x.supersedes=b.id)),'[]') else '[]'::jsonb end,
 'flowRecords',case when own then coalesce((select jsonb_agg(jsonb_build_object('taskId',t.id,'end',e.at,'start',(select min(at) from pulse_priv.delivery_event s where s.org_id=current_org() and s.task_id=t.id and s.kind='in_progress' and s.at<=e.at),'calendar',coalesce(pl.calendar->'intervals','[]'),'blockers',coalesce((select jsonb_agg(jsonb_build_object('start',started_at,'end',coalesce(ended_at,e.at),'approved',approved,'actionable',false)) from pulse_priv.delivery_blocker bl where bl.org_id=current_org() and bl.task_id=t.id and approved and not contested and kind in('input','approval','client_approval','source_outage')),'[]'))) from pulse_priv.delivery_task t join pulse_priv.delivery_event e on e.task_id=t.id and e.kind='accepted' left join pulse_priv.delivery_plan pl on pl.org_id=t.org_id and pl.project_id=t.project_id where t.org_id=current_org() and exists(select 1 from pulse_priv.fair_credit c where c.org_id=current_org() and c.acceptance_id=e.id and c.person_id=target and not exists(select 1 from pulse_priv.fair_credit x where x.supersedes=c.id))),'[]') else '[]'::jsonb end,
 'reviewRecords',case when own then coalesce((select jsonb_agg(jsonb_build_object('taskId',t.id,'policy',p.body,'reply',(select min(at) from pulse_priv.delivery_event e where e.org_id=current_org() and e.task_id=t.id and e.actor=target and e.kind in('accepted','in_progress') and e.at>=(p.body->>'startAt')::timestamptz))) from pulse_priv.delivery_task t join pulse_priv.delivery_review_policy p on p.org_id=t.org_id and p.task_id=t.id where t.org_id=current_org() and t.reviewer_id=target),'[]') else '[]'::jsonb end,
 'notes',case when own then coalesce((select jsonb_agg(body||jsonb_build_object('id',id,'version',version,'feedback',feedback)) from pulse_priv.fair_note where org_id=current_org() and person_id=target),'[]') else '[]'::jsonb end,
 'experiments',case when own then coalesce((select jsonb_agg(jsonb_build_object('id',id,'skill',skill,'hypothesis',hypothesis,'anchor',anchor,'state',state,'sample',sample,'result',result,'before',before_value,'after',after_value,'beforeVersion',(select version from pulse_priv.fair_note where id=note_id),'afterVersion',(select body->>'version' from pulse_priv.delivery_event where id=sample),'reviewer',(select display_name from person where id=reviewer))) from pulse_priv.fair_experiment where org_id=current_org() and person_id=target),'[]') else '[]'::jsonb end,
 'disputes',case when own then coalesce((select jsonb_agg(jsonb_build_object('id',id,'dimension',dimension,'reason',reason,'state',state,'resolution',resolution)) from pulse_priv.fair_dispute where org_id=current_org() and person_id=target),'[]') else '[]'::jsonb end,
 'kudos',case when own then coalesce((select jsonb_agg(jsonb_build_object('id',k.id,'sender',p.display_name,'text',message)) from pulse_priv.fair_kudos k join person p on p.id=k.sender where k.org_id=current_org() and k.recipient=target),'[]') else '[]'::jsonb end,
 'preferences',coalesce((select jsonb_build_object('extras',extras,'reducedMotion',reduced_motion,'sound',sound) from pulse_priv.fair_preference where org_id=current_org() and person_id=current_viewer()),'{"extras":true,"reducedMotion":true,"sound":false}'),
 'permissions',jsonb_build_object('review',viewer_is('admin','leadership') or exists(select 1 from person where org_id=current_org() and id<>current_viewer() and manages(id))));end $$;
